+/** Theoretical sales use, actual consumption, and actual minus theoretical by item. */
+export function varianceReport(store, from, to) {
+  const totals = new Map();
+  const entry = (id) => {
+    if (!totals.has(id)) totals.set(id, { itemId: id, theoretical: 0, actual: 0 });
+    return totals.get(id);
+  };
+  for (const sale of store.data.sales) {
+    const day = sale.soldAt.slice(0, 10);
+    if (day < from || day > to) continue;
+    for (const ingredient of sale.ingredients) entry(ingredient.itemId).theoretical += ingredient.qty;
+  }
+  for (const movement of store.data.movements) {
+    if (movement.type !== "consume" || dayOf(movement.at) < from || dayOf(movement.at) > to) continue;
+    const batch = store.data.batches.find((b) => b.id === movement.batchId);
+    if (batch) entry(batch.itemId).actual += movement.qty;
+  }
+  const round = (n) => Math.round(n * 1000) / 1000;
+  return [...totals.values()].filter((line) => line.theoretical > 0 || line.actual > 0)
+    .map((line) => ({ ...line, theoretical: round(line.theoretical), actual: round(line.actual), difference: round(line.actual - line.theoretical) }))
+    .sort((a, b) => a.itemId - b.itemId);
+}
